import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
if (mode === 'case') {
  const cases = [
    [['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']],
    [['js', 'JS', 'Js', 'jS'], ['js']],
    [['B', 'a', 'b', 'C', 'A', 'c', 'D'], ['B', 'a', 'C', 'D']],
    [['', 'A', '', 'a', ' ', ' A', ' a', 'A '], ['', 'A', ' ', ' A', 'A ']],
    [['tag-1', 'TAG-1', 'tag-2', 'TAG-2', '1', '01'], ['tag-1', 'tag-2', '1', '01']],
  ];
  for (const [input, expected] of cases) {
    const snapshot = input.slice();
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, snapshot);
  }
  // Check first-seen spelling and order throughout a large, varied ASCII list.
  const input = [];
  const expected = [];
  const seen = new Set();
  for (let i = 0; i < 100000; i++) {
    const id = (i * 7919) % 23003;
    const tag = (i % 3 === 0 ? 'TAG-' : i % 3 === 1 ? 'tag-' : 'Tag-') + id;
    input.push(tag);
    const key = tag.toLowerCase();
    if (!seen.has(key)) { seen.add(key); expected.push(tag); }
  }
  assert.deepEqual(uniqueTags(input), expected);
} else if (mode === 'regression') {
  for (const [input, expected] of [
    [[], []],
    [['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']],
    [['z', 'a', 'm', 'z', 'a', 'q'], ['z', 'a', 'm', 'q']],
    [['', '', 'x', '', 'x'], ['', 'x']],
    [['__proto__', 'constructor', 'toString', '__proto__'], ['__proto__', 'constructor', 'toString']],
  ]) {
    const frozen = Object.freeze(input.slice());
    assert.deepEqual(uniqueTags(frozen), expected);
    assert.deepEqual(frozen, input);
  }
} else if (mode === 'speed' || mode === 'benchmark') {
  const first = Array.from({length: 200000}, (_, i) => 'tag-' + i);
  const input = first.concat(mode === 'benchmark' ? first.map(t => t.toUpperCase()) : first);
  for (let i = 0; i < 3; i++) uniqueTags(first.slice(0, 1000));
  const start = performance.now();
  const result = uniqueTags(input);
  const elapsed = performance.now() - start;
  if (mode === 'speed') {
    assert.deepEqual(result, first);
    assert.ok(elapsed < 800, `400000 tags took ${elapsed.toFixed(1)} ms (limit 800 ms)`);
  } else {
    console.log(elapsed);
  }
} else {
  throw new Error('Unknown mode');
}
